//! Onshape's tool descriptions, shown in the expanded toolbar tooltip and
//! the tool search (live, part-studio/11-tooltip-extrude-expanded.png).
//! Written after the live tooltip and the help center's icon glossary
//! (/root/onshape-research/docs-raw/md/Home__icon_glossary.md), in our own
//! words where the wording isn't the tool's plain function.

/// The description of a Part Studio feature tool by feature type id.
pub fn description(id: &str) -> Option<&'static str> {
    Some(match id {
        "extrude" => "Create, add to, subtract from, or intersect parts (by extruding sketch regions or planar faces), surfaces (by extruding lines or curves), or thin parts (by extruding sketch regions, planar faces, lines, or curves).",
        "revolve" => "Create, add to, subtract from, or intersect parts, surfaces, or thin parts by revolving sketch regions, planar faces, lines, or curves around a central axis.",
        "sweep" => "Create, add to, subtract from, or intersect parts, surfaces, or thin parts by sweeping sketch regions, planar faces, lines, or curves along a path, with optional profile control, twist, and scale.",
        "loft" => "Create, add to, subtract from, or intersect parts, surfaces, or thin parts with a smooth face placed between ordered profiles.",
        "thicken" => "Create, add to, subtract from, or intersect parts by giving surfaces or faces of solids a thickness.",
        "enclose" => "Create, add to, subtract from, or intersect parts from the region enclosed by selected faces, surfaces, and parts.",
        "fillet" => "Round edges with constant, variable, partial, or asymmetric fillets, or create full round fillets. Choose the measurement (radius or width) and the control (distance, conic, or curvature).",
        "faceBlend" => "Blend two or more faces, with options for propagation, cross section, measurement, symmetry, control, and trimming.",
        "chamfer" => "Bevel edges or faces. Choose the measurement (offset or tangent) and the chamfer type (equal distance, two distances, or distance and angle).",
        "draft" => "Add a draft angle to one or more faces, measured from a neutral plane or a parting line.",
        "bodyDraft" => "Draft a part by selecting edges, faces, or the part itself.",
        "rib" => "Create ribs on selected parts from sketch curves, with a thickness, extending normal or parallel to the sketch plane.",
        "shell" => "Hollow a part into thin walls by removing one or more faces, with a wall thickness for the faces that remain.",
        "hole" => "Create simple, counterbore, or countersink holes at sketch points or mate connectors, with size, termination, standard, precision, and tolerances.",
        "externalThread" => "Add an external thread to cylindrical parts from their leading edges, with standard, size, pitch, length, and end type, and an optional chamfer or undercut.",
        "linearPattern" => "Create, add to, subtract from, or intersect copies of parts, faces, or features along a direction, with spacing and instance count, optionally skipping instances.",
        "circularPattern" => "Create, add to, subtract from, or intersect copies of parts, faces, or features around an axis, with angle and instance count, optionally skipping instances.",
        "curvePattern" => "Create, add to, subtract from, or intersect copies of parts, faces, or features along a path, with spacing and instance count, optionally skipping instances.",
        "mirror" => "Create, add to, subtract from, or intersect a mirrored copy of parts, faces, or features about a plane or planar face.",
        "booleanBodies" => "Unite, subtract, or intersect two or more parts or surfaces.",
        "splitPart" => "Split parts, surfaces, or faces. Parts and surfaces can keep or remove the split tool; faces are split by a sketch curve, curve, surface, or plane.",
        "transform" => "Move, rotate, copy, or scale parts, by mate connectors or by translating along a line, a distance, or XYZ values.",
        "wrap" => "Wrap faces or sketch entities around a cylindrical or conical part or surface, positioned by anchor points, angle, or shift.",
        "decal" => "Place an image on a flat or cylindrical face of a part or surface, with its location, size, and alignment.",
        "deleteBodies" => "Delete one or more parts or surfaces; composite parts can be deleted, dissolved, or kept.",
        "modifyFillet" => "Change the radius of existing fillets and rounds, or remove them. Useful on imported parts.",
        "deleteFace" => "Remove faces from a part and heal the surrounding faces, cap the opening, or leave it open. Useful on imported parts.",
        "moveFace" => "Translate, rotate, or offset faces by an end type and distance, or an axis and angle. Useful on imported parts.",
        "replaceFace" => "Trim or extend faces to a new surface. Useful on imported parts.",
        "cPlane" => "Create a construction plane from existing geometry.",
        "offsetSurface" => "Create a surface offset from a face, surface, or sketch region. An offset of 0 makes a copy.",
        "boundarySurface" => "Create or add to a surface defined by its boundary profiles.",
        "fill" => "Create or add to a surface bounded by a closed loop of curves or edges, with a continuity condition for each.",
        "extendSurface" => "Extend or trim the boundary edges of a surface.",
        "ruledSurface" => "Create or add a ruled surface from an edge, sketch line, or curve, with type, angle, distance, and corner type.",
        "mutualTrim" => "Trim two adjacent surfaces against each other, extending them where needed, optionally merging the result.",
        "constrainedSurface" => "Fit a surface to points or mesh data within a tolerance, tuned for performance or smoothness, with deviation display.",
        "helix" => "Create a helix from a conical or cylindrical face, an axis, or a circular edge, with start and end conditions, revolutions, and pitch.",
        "fitSpline" => "Create a curve through vertices or tangent-continuous edges, with direction, magnitude, and curvature at its ends.",
        "projectCurves" => "Create a curve by projecting a curve onto faces, or from two non-parallel sketches.",
        "bridgingCurve" => "Create a curve between two points or vertices, with a continuity condition at each end.",
        "compositeCurve" => "Join sketch entities, adjacent edges, and curves that meet at their ends into one curve.",
        "intersectionCurve" => "Create a curve where two or more surfaces or faces intersect.",
        "trimCurve" => "Trim or extend curves by a distance or to a bounding entity.",
        "isocline" => "Create isocline curves, or split faces along isoclines, from faces, an angle, and a reference direction.",
        "offsetCurveOnFace" => "Create a curve offset from edges along their surrounding faces, optionally extending or splitting.",
        "isoparametricCurve" => "Create U or V curves on a surface: evenly spaced, at a parameter value, or through a point.",
        "editCurve" => "Edit a curve or create one from sketch entities, edges, or curves: simplify, change its degree, move control vertices, or make it planar.",
        "routingCurve" => "Create a spline or polyline with optional bend radii through points placed with a manipulator, mate connectors, vertices, edge samples, or a CSV file.",
        "mateConnector" => "Create a mate connector on or between parts or surfaces, used to place and orient them in assembly mates.",
        "importDerived" => "Insert parts, sketches, surfaces, curves, planes, or mate connectors from another Part Studio through an associative link that follows its changes.",
        "assignVariable" => "Create a variable for dimensions and expressions in this Part Studio. Use it in any numeric field as # and its name.",
        "queryVariable" => "Create a query variable for use in other features of this Part Studio.",
        "compositePart" => "Group parts, surfaces, curves, points, and meshes into an open or closed composite part.",
        "tag" => "Tag geometry for frames, sheet metal forms, or PCB holes, with an orientation and properties.",
        "frame" => "Create a frame by sweeping a profile along paths of faces, edges, or vertices, with mirror, offset, angle, joint, and trim controls.",
        "frameTrim" => "Trim frame segments against each other by group order, or against a face.",
        "gusset" => "Add gussets between adjacent frame segments at selected edges, with profile, size, thickness, offset, and corner chamfer.",
        "endcap" => "Cap frame segment ends with a profile and thickness, offset larger or smaller than the segment.",
        "cutlist" => "Group frame segments into an open composite part with a table of each segment's properties.",
        "sheetMetalStart" => "Create sheet metal parts by converting parts, extruding sketches, or thickening faces or sketches. The model keeps a flat pattern with its joints and bends.",
        "sheetMetalFlange" => "Add a wall joined by a bend at each selected edge of a sheet metal part, with alignment, end type, and angle control.",
        "sheetMetalHem" => "Add hems to sheet metal parts, with hem type, base alignment, and corner type.",
        "sheetMetalTab" => "Add a tab to a sheet metal flange, removing interfering material, or bridge two flanges of the same model.",
        "sheetMetalBend" => "Bend a sheet metal model along a reference line.",
        "sheetMetalFormed" => "Add form features from a library to sheet metal parts.",
        "sheetMetalMakeJoint" => "Turn adjacent walls into a bend or rip joint, with bend radius or rip style.",
        "sheetMetalCorner" => "Change one sheet metal corner's relief type and scale.",
        "sheetMetalBendRelief" => "Change one sheet metal bend relief's type and scale.",
        "sheetMetalCornerBreak" => "Break sheet metal corners with a fillet or chamfer at a corner edge or vertex.",
        "sheetMetalEnd" => "Finish the sheet metal models so later features edit them as ordinary parts.",
        _ => return None,
    })
}

/// The description of a sketch toolbar tool (or Extrude / Revolve there)
/// by its name, as in its tooltip title ("Line", "Corner rectangle").
pub fn sketch_description(name: &str) -> Option<&'static str> {
    Some(match name {
        "Extrude" => return description("extrude"),
        "Revolve" => return description("revolve"),
        "Line" => "Sketch a line segment or a chain of line segments.",
        "Midpoint line" => "Sketch a line from its midpoint out to both ends.",
        "Corner rectangle" => "Sketch a rectangle from one corner to the opposite corner.",
        "Center point rectangle" => "Sketch a rectangle from its center point to a corner.",
        "Aligned rectangle" => "Sketch a rectangle from one side at any angle, then its width.",
        "Center point circle" => "Sketch a circle from its center point to a point on the circle.",
        "3 point circle" => "Sketch a circle through 3 points on its circumference.",
        "Ellipse" => "Sketch an ellipse from its center point, major axis, and minor axis.",
        "3 point arc" => "Sketch an arc through its 2 end points and a point on the arc.",
        "Tangent arc" => "Sketch an arc tangent to a line or arc at its end.",
        "Center point arc" => "Sketch an arc from its center, start, and end points.",
        "Elliptical arc" => "Sketch part of an ellipse from its center, axes, start, and end points.",
        "Conic" => "Sketch an ellipse, parabola, or hyperbola segment from its start, end, and control points, with a rho value.",
        "Inscribed polygon" => "Sketch a regular polygon inscribed in a circle.",
        "Circumscribed polygon" => "Sketch a regular polygon around a circle.",
        "Spline" => "Sketch a smooth curve through points; drag any point to reshape it.",
        "Bezier" => "Sketch a Bezier curve from its control polygon; drag the control points to reshape it.",
        "Spline control point" => "Add points to a spline or to a Bezier control polygon by clicking along it.",
        "Point" => "Add a point to the sketch.",
        "Text" => "Add text in a box drawn in the sketch, with a font and style.",
        "Use" | "Use (Project/Convert)" => "Project edges or faces of parts and other sketches onto the sketch plane.",
        "Intersection" => "Project where a face or surface crosses the sketch plane.",
        "Construction" => "Draw new geometry as construction geometry, or turn selected entities into construction.",
        "Fillet" | "Sketch fillet" => "Round the corner between 2 sketch entities, or at the point that joins them, with a radius.",
        "Chamfer" | "Sketch chamfer" => "Bevel the corner between 2 sketch entities, or at the point that joins them.",
        "Trim" => "Trim a curve back to the nearest intersection or boundary; with none, the whole entity is deleted.",
        "Extend" => "Extend a curve to the nearest intersection or boundary.",
        "Split" => "Split curves into segments at selected points.",
        "Offset" => "Copy sketch entities at a distance and direction from the originals.",
        "Slot" => "Draw a slot around a line, spline, arc, or closed profile.",
        "Mirror" => "Mirror sketch entities about a line or plane.",
        "Linear pattern" => "Repeat sketch entities in one or two directions, with a count and spacing.",
        "Circular pattern" => "Repeat sketch entities around a point, with a count and angle.",
        "Transform" => "Move, rotate, and scale sketch entities with a manipulator.",
        "Insert DXF or DWG" => "Insert the contents of a DXF or DWG file as sketch entities.",
        "Insert image" => "Insert an image to trace over.",
        "Dimension" => "Add dimensions to and between sketch entities.",
        "Coincident" => "Make 2 or more sketch entities share the same location.",
        "Concentric" => "Put a point at the center of an arc or circle, or give arcs and circles a common center.",
        "Parallel" => "Make 2 or more lines parallel.",
        "Tangent" => "Make 2 sketch entities tangent, or an entity tangent to a plane.",
        "Horizontal" => "Make lines, or sets of points, horizontal.",
        "Vertical" => "Make lines, or sets of points, vertical.",
        "Perpendicular" => "Make 2 lines perpendicular.",
        "Equal" => "Make lines equal in length, or arcs and circles equal in radius.",
        "Midpoint" => "Put a point at the midpoint of a line or arc.",
        "Normal" => "Make a curve and a line, or a curve and a plane, perpendicular.",
        "Pierce" => "Put a sketch point where an entity outside the sketch plane crosses it.",
        "Symmetric" => "Make 2 entities of the same type symmetric about a line, plane, or edge.",
        "Fix" => "Lock sketch entities where they are on the sketch plane.",
        "Curvature" => "Give splines or conics curvature-continuous joins with the geometry around them.",
        _ => return None,
    })
}
